<?php namespace App\Console\Commands;use Illuminate\Console\Command;use App\Models\AbandonedCart;use App\Models\AbandonedCartReminder;class ProcessAbandonedCarts extends Command{protected $signature='shoply:abandoned-carts';protected $description='Record reminder jobs for abandoned carts older than one hour.';public function handle(){ $count=0;AbandonedCart::whereNull('reminded_at')->where('updated_at','<=',now()->subHour())->chunkById(100,function($carts)use(&$count){foreach($carts as $cart){AbandonedCartReminder::create(['abandoned_cart_id'=>$cart->id,'channel'=>'database','sent_at'=>now()]);$cart->update(['reminded_at'=>now()]);$count++;}});$this->info("Processed {$count} abandoned carts.");return self::SUCCESS;}}
